referenceSolutions.javascript:
export function longestValidParentheses(text        )         {
const s=[-1];let best=0;for(let i=0;i<text.length;i++){if(text[i]==='(')s.push(i);else{s.pop();if(!s.length)s.push(i);else best=Math.max(best,i-s[s.length-1]);}}return best;
}

